/* COVER */
.cover{position:fixed;inset:0;z-index:5000;background:#0d0907;display:grid;grid-template-columns:1fr 1fr;transition:opacity .8s,visibility .8s}.cover.hide{opacity:0;visibility:hidden}.cover-photo{background:linear-gradient(90deg,transparent 55%,#0d0907),url('https://images.unsplash.com/photo-1519741497674-611481863552?q=85&w=1600&auto=format&fit=crop') center/cover}.cover-copy{display:flex;align-items:center;padding:7vw;position:relative}.cover-copy:before{content:'';position:absolute;inset:26px;border:1px solid var(--line)}.cover-inner{position:relative;z-index:2}.cover-name{font-size:clamp(48px,8vw,94px);line-height:.9;margin:18px 0}.guest-box{border-left:2px solid var(--gold);padding-left:18px;margin:26px 0;color:var(--muted)}
/* HERO editorial split */
.hero{min-height:100vh;position:relative;display:grid;align-items:end;padding:120px 0 60px;background:#17100d;overflow:hidden}.hero-media{position:absolute;inset:0 0 0 38%;}.hero-media img{width:100%;height:100%;object-fit:cover;filter:saturate(.75) contrast(1.06)}.hero-media:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#17100d 0%,rgba(23,16,13,.78) 16%,rgba(23,16,13,.12) 62%),linear-gradient(0deg,#17100d 0%,transparent 38%)}.hero-copy{position:relative;z-index:2;width:min(610px,90%)}.hero-name{font-size:clamp(62px,11vw,144px);line-height:.76;letter-spacing:-.065em;margin:26px 0 30px}.hero-date{display:flex;gap:26px;align-items:center;color:var(--paper);font-size:13px;letter-spacing:.16em;text-transform:uppercase}.hero-date:before{content:'';width:72px;height:1px;background:var(--gold)}.vertical-word{position:absolute;right:22px;top:50%;z-index:3;writing-mode:vertical-rl;letter-spacing:.45em;text-transform:uppercase;font-size:10px;color:rgba(255,255,255,.65)}
