/* music */
.music-player{position:fixed;right:18px;bottom:18px;z-index:4500;display:flex;align-items:center;gap:10px}.music-label{background:#0d0907;border:1px solid var(--line);padding:8px 12px;font-size:10px;letter-spacing:.15em;text-transform:uppercase}.music-btn{width:54px;height:54px;border-radius:50%;border:1px solid var(--gold);background:#17100d;color:var(--gold);font-size:20px}.music-btn.playing{animation:pulse 1.8s infinite}@keyframes pulse{50%{box-shadow:0 0 0 10px rgba(214,184,117,0)}}
.floating-petal{position:fixed;top:-20px;z-index:4000;pointer-events:none;animation:fall linear forwards;color:#ead9bd}@keyframes fall{to{transform:translate3d(var(--x),110vh,0) rotate(540deg);opacity:.1}}
@media(max-width:800px){.cover{grid-template-columns:1fr}.cover-photo{position:absolute;inset:0;opacity:.32;background-image:linear-gradient(#0d0907aa,#0d0907dd),url('https://images.unsplash.com/photo-1519741497674-611481863552?q=80&w=1200&auto=format&fit=crop')}.cover-copy{padding:32px}.hero{align-items:center;padding-top:90px}.hero-media{inset:0;opacity:.48}.hero-media:after{background:linear-gradient(0deg,#17100d 3%,rgba(23,16,13,.45) 50%,#17100d 100%)}.hero-copy{width:100%}.hero-name{font-size:64px}.intro-grid{grid-template-columns:1fr;gap:55px}.monogram{width:180px;height:180px}.event-panel{grid-template-columns:1fr}.event-column{padding:38px 24px}.event-column+.event-column{border-left:0;border-top:1px solid var(--line)}.countdown{grid-template-columns:repeat(2,1fr)}.count-item:nth-child(2){border-right:0}.count-item:nth-child(-n+2){border-bottom:1px solid var(--line)}.ribbon{background-attachment:scroll}.gallery-grid{grid-template-columns:1fr;grid-auto-rows:320px}.gallery-card,.gallery-card:nth-child(n){grid-column:1!important;grid-row:auto!important}.wish-list{grid-template-columns:1fr}.vertical-word{display:none}.section{padding:75px 0}}
