<script>
const cover=document.getElementById('cover'),openBtn=document.getElementById('openInvitation'),audio=document.getElementById('bgMusic'),musicBtn=document.getElementById('musicToggle'),musicLabel=document.getElementById('musicLabel');
function setMusicUI(on){if(!musicBtn)return;musicBtn.classList.toggle('playing',on);musicBtn.innerHTML=on?'<i class="bi bi-pause-fill"></i>':'<i class="bi bi-music-note-beamed"></i>';if(musicLabel)musicLabel.textContent=on?'Music On':'Music Off'}
openBtn?.addEventListener('click',()=>{cover.classList.add('hide');document.body.style.overflow='auto';if(audio)audio.play().then(()=>setMusicUI(true)).catch(()=>setMusicUI(false));for(let i=0;i<14;i++)setTimeout(dropPetal,i*110)});document.body.style.overflow='hidden';
musicBtn?.addEventListener('click',()=>{if(!audio)return;if(audio.paused)audio.play().then(()=>setMusicUI(true));else{audio.pause();setMusicUI(false)}});
function dropPetal(){const p=document.createElement('span');p.className='floating-petal';p.textContent=Math.random()>.5?'✦':'❀';p.style.left=Math.random()*100+'vw';p.style.setProperty('--x',(Math.random()*180-90)+'px');p.style.animationDuration=(5+Math.random()*5)+'s';document.body.appendChild(p);setTimeout(()=>p.remove(),10000)}
const cd=document.getElementById('countdown');if(cd){const target=new Date(cd.dataset.date+'T00:00:00').getTime();function tick(){let d=Math.max(0,target-Date.now());document.getElementById('cdDays').textContent=Math.floor(d/86400000);document.getElementById('cdHours').textContent=Math.floor(d%86400000/3600000);document.getElementById('cdMinutes').textContent=Math.floor(d%3600000/60000);document.getElementById('cdSeconds').textContent=Math.floor(d%60000/1000)}tick();setInterval(tick,1000)}
</script>
